const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=x=>Math.abs(x)<.0005?'0.000':Number(x).toFixed(3);
const ids=n=>n?[n.id,...ids(n.left),...ids(n.right)]:[];
function tree(panel,f,index){
 if(!panel.root)return '<div class="lesson-empty">∅<span>空子树</span></div>';
 // Tidy contours keep subtrees apart while avoiding a wide diagonal for chains.
 function tidy(n){if(!n)return null;const l=tidy(n.left),r=tidy(n.right);let gap=55;
  if(l&&r)for(let d=0;d<Math.min(l.max.length,r.min.length);d++)gap=Math.max(gap,(l.max[d]-r.min[d]+112)/2);
  const nodes=[{n,x:0,d:0}],edges=[];
  for(const [t,offset] of [[l,l&&r?-gap:-35],[r,l&&r?gap:35]])if(t){nodes.push(...t.nodes.map(p=>({...p,x:p.x+offset,d:p.d+1})));edges.push([0,0,offset,1],...t.edges.map(([a,b,c,d])=>[a+offset,b+1,c+offset,d+1]));}
  const min=[],max=[];for(const p of nodes){min[p.d]=Math.min(min[p.d]??Infinity,p.x);max[p.d]=Math.max(max[p.d]??-Infinity,p.x)}return{nodes,edges,min,max};
 }
 const packed=tidy(panel.root),min=Math.min(...packed.min),max=Math.max(...packed.max),offset=65-min,w=Math.max(230,max-min+130),h=(packed.min.length-1)*104+135;
 const nodes=packed.nodes.map(p=>({n:p.n,x:p.x+offset,y:44+p.d*104})),edges=packed.edges.map(([a,b,c,d])=>[a+offset,44+b*104,c+offset,44+d*104]);
 const sets=f.teaching?.proof?.sets||[];
 return `<div class="lesson-tree-scroll"><svg viewBox="0 0 ${w} ${h}" style="width:${w}px" role="img" aria-label="${e(panel.label)}，键值与节点编号、元数据">${edges.map(([x,y,a,b])=>`<path class="edge" d="M${x} ${y+23}L${a} ${b-23}"/>`).join('')}${nodes.map(({n,x,y})=>{const group=sets.findIndex(s=>s.ids.includes(n.id));return `<g data-node="${n.id}" data-panel="${index}" data-x="${x}" data-y="${y}" transform="translate(${x} ${y})">${group>=0?`<circle r="32" class="set-ring set-${group}"/>`:''}<circle r="23" class="node ${f.hot?.includes(n.id)?'hot':''}"/><text y="5" text-anchor="middle" font-size="17">${n.v}</text><text y="-30" text-anchor="middle" class="node-role">${e(n.role)}</text><text y="43" text-anchor="middle" font-size="13">${e(n.id)}${n.role?' · '+e(n.role):''}</text><text y="61" text-anchor="middle" font-size="12">${e(n.note)}</text>${f.mode==='avl'&&n.h!==n.heightActual?`<text y="78" text-anchor="middle" class="stale-height">缓存待更新 · 真 h=${n.heightActual}</text>`:''}</g>`}).join('')}</svg></div>`;
}
export function renderLessonTree(f){return `<div class="lesson-forest ${f.panels.length>1?'paired':''}">${f.panels.map((p,i)=>`<section class="lesson-tree-panel"><h4>${e(p.label)}</h4>${tree(p,f,i)}</section>`).join('')}</div>`}
function code(t){return `<details class="live-code" open><summary>与当前步骤对应的伪代码</summary><pre>${t.code.map((line,i)=>`<span class="code-line ${t.lines?.includes(i+1)?'current-line':''}"><b>${i+1}</b>${e(line)}</span>`).join('')}</pre></details>`}
function bars(p){const vals=[p.c,p.delta,p.amortized],max=Math.max(1,...vals.map(Math.abs));return `<div class="cost-bars" aria-label="旋转成本、势能差与均摊成本，有符号比较">${vals.map((v,i)=>`<div class="cost-row"><span>${['c · 旋转','ΔΦ · 势能差','ĉ · 均摊'][i]}</span><div class="cost-track"><i style="left:${v<0?50+v/max*48:50}%;width:${Math.abs(v)/max*48}%" class="${v<0?'negative':''}"></i></div><b>${num(v)}</b></div>`).join('')}<small>中线为 0；左侧表示负值。ĉ 为负说明势能释放超过本轮旋转成本。</small></div>`}
function derivation(p){const row=role=>p.rows.find(r=>r.role===role),x=row('x'),a=row('p'),g=row('g');let steps;
 if(p.type==='Zig')steps=[`只有 x、p 的秩变化，且 r′(x)=r(p)。`,`ĉ = 1 + r′(p) − r(x) = ${num(p.amortized)}`,`r′(p) ≤ r′(x)，所以 ĉ ≤ 1 + Δr(x) ≤ 1 + 3Δr(x) = ${num(p.bound)}。`];
 else if(p.type==='Zig-zig')steps=[`x、p、g 以外的节点子树集合不变；r′(x)=r(g)。`,`ĉ = 2 + r′(p) + r′(g) − r(x) − r(p)`,`由 r′(p)≤r′(x)、r(p)≥r(x)，得 ĉ ≤ 2 + r′(x) + r′(g) − 2r(x)。`,`旧 x 子树与新 g 子树不相交：r(x)+r′(g) ≤ 2r′(x)−2。`,`代入消去常数 2，得 ĉ ≤ 3[r′(x)−r(x)] = ${num(p.bound)}。`];
 else steps=[`只有 x、p、g 的秩变化，且 r′(x)=r(g)。`,`ĉ = 2 + r′(p) + r′(g) − r(x) − r(p)`,`新 p、g 子树不相交：r′(p)+r′(g) ≤ 2r′(x)−2。`,`由 r(p)≥r(x)，得 ĉ ≤ 2[r′(x)−r(x)] ≤ 3Δr(x) = ${num(p.bound)}。`];
 return `<div class="round-proof"><h3>${e(p.type)}：把图上的数代回证明</h3><ol>${steps.map(s=>`<li>${e(s)}</li>`).join('')}</ol><div class="formula">Δr(x) = ${num(x.afterRank)} − ${num(x.rank)} = ${num(p.rankGain)}<br>ĉ = ${num(p.amortized)} ≤ ${num(p.bound)}　✓</div>${p.sets?`<div class="disjoint-sets"><h4>为什么会出现 −2？</h4><p>两组节点不相交，大小分别为 a、b，且 a+b ≤ s′(x)=${p.container}。由 ab ≤ ((a+b)/2)²：</p>${p.sets.map((s,i)=>`<div><span class="set-label set-${i}">${e(s.label)} · ${s.ids.length} 个</span> ${s.ids.map(id=>`<span class="set-chip set-${i}">${e(id)}</span>`).join('')}</div>`).join('')}<div class="formula">log₂a + log₂b = ${num(p.setRankSum)}<br>≤ 2log₂(a+b) − 2 ≤ 2r′(x) − 2 = ${num(p.logUpper)}</div><p>颜色对应上方树图中的节点集合；集合成员以稳定编号识别。</p></div>`:''}</div>`;
}
function rankTable(p){return `<div class="table-wrap"><table class="rank-table"><caption>逐节点秩账本：ΣΔr = ΔΦ = ${num(p.delta)}</caption><thead><tr><th>节点 / 角色</th><th>s → s′</th><th>r → r′</th><th>Δr</th></tr></thead><tbody>${p.rows.map(r=>`<tr class="${r.role==='不变'?'':'rank-changed'}"><td>${r.v} · ${r.id} / ${e(r.role)}</td><td>${r.size} → ${r.afterSize}</td><td>${num(r.rank)} → ${num(r.afterRank)}</td><td>${num(r.delta)}</td></tr>`).join('')}</tbody></table></div>`}
function ledger(l){const h=l.history,last=h.at(-1),phi=last?.phiAfter??l.phi0,range=Math.max(1,...h.flatMap(x=>[x.totalC,Math.abs(x.totalA),x.phiAfter]),l.phi0),Y=v=>142-v/range*105,X=i=>45+i*490/Math.max(1,h.length);const series=[{name:'累计旋转 Σc',color:'#235e4b',vals:[0,...h.map(x=>x.totalC)]},{name:'累计均摊 Σĉ',color:'#b5763a',vals:[0,...h.map(x=>x.totalA)]},{name:'势能 Φ',color:'#677bb8',vals:[l.phi0,...h.map(x=>x.phiAfter)]}];
 return `<section class="sequence-ledger"><h3>整段访问序列：势能如何抵消</h3><p>这里只结算已经完成的访问；双旋的中间帧不会提前入账。每个点对应一次完整访问。</p><svg class="ledger-chart" viewBox="0 0 590 285" role="img" aria-label="已完成访问的累计旋转、累计均摊成本和势能趋势"><path d="M45 22V250H550M45 142H550" fill="none" stroke="#c2cfbd"/>${[range,0,-range].map(v=>`<text x="38" y="${Y(v)+4}" text-anchor="end" font-size="11">${num(v)}</text>`).join('')}${series.map(s=>`<polyline points="${s.vals.map((v,i)=>`${X(i)},${Y(v)}`).join(' ')}" fill="none" stroke="${s.color}" stroke-width="2.5"/>${s.vals.map((v,i)=>`<circle cx="${X(i)}" cy="${Y(v)}" r="3.5" fill="${s.color}"/>`).join('')}`).join('')}<text x="45" y="272" font-size="12">初始</text><text x="535" y="272" font-size="12" text-anchor="end">已完成 ${h.length} 次访问</text></svg><div class="chart-legend">${series.map(s=>`<span><i style="background:${s.color}"></i>${s.name}</span>`).join('')}</div><div class="formula">Σc = Σĉ + Φ₀ − Φfinal<br>${num(l.totalC)} = ${num(l.totalA)} + ${num(l.phi0)} − ${num(phi)}</div>${h.length?`<div class="table-wrap"><table><thead><tr><th>访问</th><th>c</th><th>ΔΦ</th><th>ĉ</th><th>引理上界</th></tr></thead><tbody>${h.map(x=>`<tr><td>${x.index}. key=${x.key}</td><td>${x.c}</td><td>${num(x.delta)}</td><td>${num(x.amortized)}</td><td>${num(x.bound)}</td></tr>`).join('')}</tbody></table></div>`:''}<p>每次访问上界为 3log₂(n/s<sub>before</sub>(x))+1。对任意初始树，这个势能证明给出 Σc ≤ m(3log₂n+1)+Φ₀；Φ₀ ≤ nlog₂n，不能无条件删去初始项。</p></section>`;
}
export function renderLessonDetail(f){const t=f.teaching;if(!t)return'';const p=t.proof;return `<div class="teaching-detail"><div class="teaching-heading"><span class="tag">操作剖面</span><h3>${e(t.phase)}</h3></div>${f.mode==='avl'?'<p class="detail-hint">节点编号 n1、n2…代表对象身份；圆内数字是键。h 与 BF 使用缓存，结构修改后的暂时旧值会另行标注。空树 h=−1。</p>':f.mode==='potential'?'<p class="detail-hint">s 是子树节点数，r=log₂s，Φ 是所有节点秩之和。c 仅统计旋转；实际查找与维护成本为 O(c+1)。这些数值是证明的具体实例，通用推导在下方与“推导与证明”页。</p>':'<p class="detail-hint">颜色突出 x（目标）、p（父亲）、g（祖父）。拆树后 L 和 R 同时保留在画面中；s、r 用于观察，标准 Splay 无需维护这些值。</p>'}${t.checks?`<div class="invariant-checks">${t.checks.map(c=>`<span class="${c.ok?'holds':'pending'}">${c.ok?'✓':'◷'} ${e(c.label)}</span>`).join('')}</div>`:''}${t.stack?.length?`<div class="call-stack"><b>递归调用栈 · 外层 → 当前</b><div>${t.stack.map(s=>`<span>${e(s)}</span>`).join('<i>→</i>')}</div></div>`:''}${t.pointers?.length?`<div class="pointer-list"><h4>本步引用 / 元数据更新</h4>${t.pointers.map(([a,b])=>`<div><code>${e(a)}</code><span>← ${e(b)}</span></div>`).join('')}</div>`:''}${t.halfRound?'<div class="note">双旋只完成了一半。观察指针如何重连，下一步才合计 c=2 并核对整轮不等式。</div>':''}${p?`<div class="proof-dashboard"><section><h3>这一轮的成本账本</h3><div class="formula">Φ: ${num(p.phiBefore)} → ${num(p.phiAfter)}<br>ĉ = c + ΔΦ = ${p.c} + (${num(p.delta)}) = ${num(p.amortized)}</div>${bars(p)}${rankTable(p)}</section>${derivation(p)}</div>`:''}${code(t)}${f.ledger?ledger(f.ledger):''}</div>`}
